import{_ as a,C as i,o as r,c as o,j as t,a as l,E as n,ak as d}from"./chunks/framework.sV-XtlWr.js";const m=JSON.parse(`{"title":"Agent skills","description":"Seven SKILL.md files, installed by the reporter's CLI, that teach a coding agent what to do with Piwi's evidence: investigate a failure, heal a locator, fix a flaky test, write the missing one.","frontmatter":{"title":"Agent skills","description":"Seven SKILL.md files, installed by the reporter's CLI, that teach a coding agent what to do with Piwi's evidence: investigate a failure, heal a locator, fix a flaky test, write the missing one.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/agent-skills.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/agent-skills.html"}],["meta",{"property":"og:title","content":"Agent skills | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Seven SKILL.md files, installed by the reporter's CLI, that teach a coding agent what to do with Piwi's evidence: investigate a failure, heal a locator, fix a flaky test, write the missing one."}]]},"headers":[],"relativePath":"features/agent-skills.md","filePath":"features/agent-skills.md","lastUpdated":1791439514000}`),h={name:"features/agent-skills.md"};function c(p,e,k,g,f,u){const s=i("Needs");return r(),o("div",null,[e[0]||(e[0]=t("h1",{id:"agent-skills",tabindex:"-1"},[l("Agent skills "),t("a",{class:"header-anchor",href:"#agent-skills","aria-label":'Permalink to "Agent skills"'},"​")],-1)),n(s,{reporter:""}),e[1]||(e[1]=d(`<p>The <a href="/features/mcp.html">MCP server</a> gives an agent read access to your results; <strong>skills</strong> tell it what to <em>do</em> with them. A skill is a single <code>SKILL.md</code> file, the portable open format (front matter plus Markdown instructions) that Claude Code and other coding agents read from a project&#39;s skills directory. Piwi ships seven, and the reporter&#39;s CLI installs them into your test project.</p><h2 id="what-each-skill-does" tabindex="-1">What each skill does <a class="header-anchor" href="#what-each-skill-does" aria-label="Permalink to &quot;What each skill does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>What it does</th></tr></thead><tbody><tr><td><code>setup-piwi</code></td><td>Wire a Playwright project up to a dashboard: the same work <code>npx @piwitests/reporter init</code> does, driven by an agent.</td></tr><tr><td><code>investigate-failure</code></td><td>Investigate a failed run and propose a fix grounded in Piwi&#39;s evidence: error, steps, console, network, and the diff since the last green run.</td></tr><tr><td><code>apply-locator-healing</code></td><td>Replace a brittle locator with Piwi&#39;s ranked <a href="/features/locator-healing.html">healed locator</a> at its call site, then re-run to confirm.</td></tr><tr><td><code>stabilize-flaky-tests</code></td><td>Reproduce the highest-impact <a href="/features/flaky-tests.html">flaky tests</a> with the <a href="/features/flake-lab.html">Flake Lab</a>, fix what the reproducing condition points at (never by adding retries), then prove it with <code>piwi flake verify</code>.</td></tr><tr><td><code>run-the-right-tests</code></td><td>After a UI change, fix the locators it breaks with <a href="/features/preflight.html">preflight</a>; then pick and run the right <a href="/features/test-selection.html">selection</a> for the task (smoke, recently broken, a time budget) instead of the whole suite.</td></tr><tr><td><code>write-the-missing-test</code></td><td>Take the top <a href="/features/scenario-gaps.html">scenario gap</a> in scope, draft it from the graph, finish the assertion and add it in the same change.</td></tr><tr><td><code>fix-a-reported-bug</code></td><td>Take a <a href="/features/bug-reports.html">bug report</a>, write its failing test with <code>piwi bug &lt;id&gt; --write</code>, reproduce, fix, then remove <code>test.fail()</code> and run the spec and the tests that visit the page.</td></tr></tbody></table><p>Each skill prefers a connected Piwi <a href="/reference/mcp-tools.html">MCP tool</a> and falls back to the dashboard UI when MCP is not connected, so a skill works before the MCP server is set up, only more slowly.</p><h2 id="what-agents-report-back" tabindex="-1">What agents report back <a class="header-anchor" href="#what-agents-report-back" aria-label="Permalink to &quot;What agents report back&quot;">​</a></h2><p>Each workflow skill ends by telling Piwi what the agent did, so the next diagnosis, the fix verification and the gap detectors learn from it:</p><table tabindex="0"><thead><tr><th>Skill</th><th>Reports back with</th></tr></thead><tbody><tr><td><code>investigate-failure</code></td><td><code>record_diagnosis</code> (its own diagnosis, shown as written by an agent), <code>submit_diagnosis_feedback</code> (a rating of Piwi&#39;s) and <code>report_fix_attempt</code> (the change, its commit and the diagnosis it followed)</td></tr><tr><td><code>apply-locator-healing</code></td><td><code>report_fix_attempt</code> with the locator edit</td></tr><tr><td><code>write-the-missing-test</code></td><td><code>triage_gap</code> (accepted, covered by a test, or dismissed with a reason)</td></tr></tbody></table><p>The fix&#39;s commit carries a <code>Piwi-Cluster: &lt;id&gt;</code> trailer, the line <code>get_fix_plan</code> suggests. When the cluster&#39;s tests pass on a later commit, Piwi records the attempt <strong>verified</strong>, tied by its commit, the trailer or its branch; a later failure records it <strong>regressed</strong>. The cluster page&#39;s <strong>Activity</strong> section lists every attempt and every write an agent made to the cluster over MCP, with the API key it used.</p><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>The skills ship inside the reporter package. <code>npx @piwitests/reporter init</code> installs the six workflow skills as part of setup (everything but <code>setup-piwi</code>, which an agent runs before the reporter exists). The <strong>MCP server</strong> page of the dashboard (<code>/mcp</code>) lists them next to the tools.</p><h2 id="use-it" tabindex="-1">Use it <a class="header-anchor" href="#use-it" aria-label="Permalink to &quot;Use it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # install all seven into .claude/skills/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # see what each one does</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> investigate-failure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .cursor/skills</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # one skill, elsewhere</span></span></code></pre></div><p>Invoke the CLI through the package name so npx resolves this package; a plain <code>npx piwi …</code> works once the reporter is a project dependency. <code>init</code> takes <code>--skills &lt;list&gt;</code> (or <code>all</code>, <code>none</code>), <code>--skills-dir</code> and <code>--no-skills</code> to change what setup installs. The <a href="/reference/cli.html#skills">CLI reference</a> lists every flag.</p><p>The skills are agent-agnostic Markdown: only the destination is tool-specific, so <code>--dir</code> points the install wherever your agent reads skills from. Each installed file carries <code>piwi-version</code> and <code>piwi-hash</code> in its front matter. A later <code>skills add</code> replaces a skill you never touched that an older release installed, reporting it <strong>outdated</strong>, and keeps one you <strong>edited</strong> unless you pass <code>--force</code>.</p><p>On the <a href="/features/desktop.html">desktop app</a>, the MCP server page also installs the workflow skills into a project&#39;s linked folder, with the same rules.</p><p>Once installed, ask in plain words: &quot;why did the last CI run fail&quot;, &quot;fix the flaky checkout test&quot;, &quot;write the test we&#39;re missing for this change&quot;. The agent picks the skill whose description matches.</p><h2 id="prompts-the-no-install-alternative" tabindex="-1">Prompts, the no-install alternative <a class="header-anchor" href="#prompts-the-no-install-alternative" aria-label="Permalink to &quot;Prompts, the no-install alternative&quot;">​</a></h2><p>The MCP server also serves every workflow skill as a <strong>prompt</strong>, which a client shows as a slash command with nothing to install: <code>investigate_failure</code>, <code>apply_locator_healing</code> and the rest, each with an optional <code>focus</code> (a run, a cluster, a test). The text is the skill shipped with the server&#39;s own version. A <code>setup_piwi</code> prompt knows this instance&#39;s URL, whether it requires an API key and its existing projects, which a static skill cannot. Prompts need MCP; installed skills work offline. See <a href="/features/mcp.html#prompts">MCP server</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Instructions, not code.</strong> A skill tells an agent which evidence to read and in which order; the agent still writes the fix, and you review it.</li><li><strong>Updated with the reporter.</strong> A newer reporter ships newer skills; <code>skills add</code> updates the copies you never edited, and <code>--force</code> replaces the edited ones too.</li><li><strong>Reporting back needs write access.</strong> The write-back tools need a key whose owner holds the matching <a href="/operate/project-access.html#what-each-role-can-do">project role</a> (Maintainer covers all of them); with a Viewer&#39;s key the agent reports what it did to you instead.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/mcp.html">MCP server</a>: the tools the skills call</li><li><a href="/reference/mcp-tools.html">MCP tools</a>: every tool, by module</li><li><a href="/reference/cli.html#skills">Piwi CLI: skills</a>: every flag of <code>skills</code> and <code>init</code></li></ul>`,22))])}const y=a(h,[["render",c]]);export{m as __pageData,y as default};
